// Needs n8n env: N8N_BLOCK_ENV_ACCESS_IN_NODE=false, N8N_LLM_TOKEN, GEMINI_API_KEYS,
// GROQ_API_KEYS, OPENROUTER_API_KEYS (comma-separated lists).
const req = $input.first().json;
if (!$env.N8N_LLM_TOKEN || (req.headers || {})['x-token'] !== $env.N8N_LLM_TOKEN)
  return [{ json: { error: 'forbidden' } }];
const prompt = (req.body || {}).prompt;
const temperature = (req.body || {}).temperature ?? 1;
const keys = (n) => String($env[n] || '').split(',').map((s) => s.trim()).filter(Boolean);
const entries = [];
keys('GEMINI_API_KEYS').forEach((k, i) => String($env.GEMINI_MODELS || 'gemini-3.5-flash-lite,gemini-3.6-flash').split(',').map((m) => m.trim()).filter(Boolean)
  .forEach((m) => entries.push({ id: 'gemini#' + i + ':' + m, type: 'gemini', key: k, model: m, prio: 1 })));
keys('GROQ_API_KEYS').forEach((k, i) => entries.push(
  { id: 'groq#' + i, type: 'groq', key: k, model: 'llama-3.3-70b-versatile', prio: 2 }));
keys('OPENROUTER_API_KEYS').forEach((k, i) => entries.push(
  { id: 'openrouter#' + i, type: 'openrouter', key: k, model: 'meta-llama/llama-3.3-70b-instruct:free', prio: 3 }));
const sd = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);
if (sd.day !== today) { sd.day = today; sd.counts = {}; sd.cool = {}; sd.fails = {}; }
const now = Date.now();
const midnight = new Date(today + 'T00:00:00Z').getTime() + 86400000;
const usable = entries.filter((e) => !(sd.cool[e.id] > now))
  .sort((a, b) => a.prio - b.prio || (sd.counts[a.id] || 0) - (sd.counts[b.id] || 0));
for (const e of usable) {
  try {
    let url, headers = { 'content-type': 'application/json' }, body;
    if (e.type === 'gemini') {
      url = 'https://generativelanguage.googleapis.com/v1beta/models/' + e.model + ':generateContent';
      headers['x-goog-api-key'] = e.key;
      body = { contents: [{ parts: [{ text: prompt }] }],
        generationConfig: { responseMimeType: 'application/json', temperature } };
    } else {
      url = e.type === 'groq' ? 'https://api.groq.com/openai/v1/chat/completions'
        : 'https://openrouter.ai/api/v1/chat/completions';
      headers.authorization = 'Bearer ' + e.key;
      body = { model: e.model, temperature, messages: [{ role: 'user', content: prompt + (e.type === 'groq' ? '' : '\nReturn only a JSON object.') }] };
      if (e.type === 'groq') body.response_format = { type: 'json_object' };
    }
    const r = await this.helpers.httpRequest({ method: 'POST', url, headers, body, json: true, timeout: 90000 });
    const text = e.type === 'gemini' ? r.candidates[0].content.parts[0].text : r.choices[0].message.content;
    sd.counts[e.id] = (sd.counts[e.id] || 0) + 1;
    return [{ json: { text, model: e.id } }];
  } catch (err) {
    const code = String(err.httpCode || err.statusCode || '');
    sd.fails[e.id] = (sd.fails[e.id] || 0) + 1;
    if (code === '429' || code === '403') {
      const msg = JSON.stringify(err.description || err.message || '').toLowerCase();
      sd.cool[e.id] = /day|daily|quota/.test(msg) ? midnight : now + 120000;
    } else if (code === '404' || code === '400') {
      sd.cool[e.id] = midnight;   // wrong model name or bad key: stop trying today
    }
  }
}
return [{ json: { error: 'all providers exhausted' } }];

// EDIT these two values after import
const REPO = 'YOUR_GITHUB_USER/yt-factory';
const OWNER_CHAT = 'YOUR_TELEGRAM_CHAT_ID';
const sd = $getWorkflowStaticData('global');
const counts = sd.counts || {}, cool = sd.cool || {}, fails = sd.fails || {};
const now = Date.now();
const lines = ['Лимиты LLM за ' + (sd.day || 'сегодня') + ' (UTC), запросов через ротатор:'];
const ids = Object.keys({ ...counts, ...fails });
if (!ids.length) lines.push('- запросов не было');
for (const id of ids) {
  const off = cool[id] > now ? ' [пауза до ' + new Date(cool[id]).toISOString().slice(11, 16) + ' UTC]' : '';
  lines.push('- ' + id + ': ' + (counts[id] || 0) + ' ok, ' + (fails[id] || 0) + ' ошибок' + off);
}
lines.push('Ориентиры бесплатных тарифов: Groq 70B около 1000 запросов в день, OpenRouter free 50 в день, '
  + 'лимит Gemini смотрите в AI Studio.');
return [{ json: { text: lines.join('\n'), chat: OWNER_CHAT } }];
